const input = $input.first().json;
const body = (typeof input.body === 'object' && input.body !== null) ? input.body : input;

const eventType  = body.event_type    || body.eventType    || '';
const entityType = body.entity_type   || body.entityType   || '';
const entityId   = body.entity_id     || body.entityId     || '';
const dealerId   = body.dealer_id     || body.dealerId     || '';
const vehicleId  = body.vehicle_id    || body.vehicleId    || '';
const data       = body.data          || body.payload      || body;
const createdAt  = body.created_at    || new Date().toISOString();

const SUPPORTED_EVENTS = [
  'lead.created',
  'custom_request.created',
  'search_alert.created',
  'vehicle.approved',
  'vehicle.rejected',
  'vehicle.submitted_for_review',
  'appointment.created'
];

if (!SUPPORTED_EVENTS.includes(eventType)) {
  return [{ json: { ok: false, reason: `event_type no soportado: ${eventType}`, eventType } }];
}

return [{
  json: {
    ok: true,
    eventType,
    entityType,
    entityId,
    dealerId,
    vehicleId,
    data,
    createdAt,
    rawBody: body
  }
}];

const legalFooter = `<div style="margin-top:24px;padding-top:14px;border-top:1px solid #ddd;font-size:11px;color:#777;line-height:1.5">Black Label Market es una marca de <strong>KAZAWEB, S.L.U.</strong> (NIF B42761254), con domicilio en Lugar Rebordelo nº 35, Planta 2, 15930 Boiro, A Coruña. Inscrita en el Registro Mercantil de Santiago de Compostela, Tomo 395, Folio 51, Hoja SC-51053.<br>Puedes solicitar la baja de comunicaciones o ejercer tus derechos de privacidad escribiendo a <a href="mailto:privacidad@blacklabelmarket.es">privacidad@blacklabelmarket.es</a>. Consulta nuestra <a href="https://blacklabelmarket.es/legal/privacidad">Política de Privacidad</a>.</div>`;

// Entrada: $json = resultado del lookup (vehículo + dealer embebido desde Supabase).
// El evento original (contacto del comprador) se lee de "Normalizar evento".
const ev = $('Normalizar evento').first().json;
const d = ev.data || {};
let look = $input.first().json || {};
// PostgREST con Accept pgrst.object devuelve content-type que n8n no parsea →
// el cuerpo llega como string JSON en look.data. Parsearlo si procede.
if (look && typeof look.data === 'string') { try { look = JSON.parse(look.data); } catch (e) {} }

const MAIL_FROM  = 'Black Label Market <hola@blacklabelmarket.es>';
const MARKET_URL = 'https://blacklabelmarket.es';

const buyerName  = d.contact?.name  || d.buyer_name  || d.name  || 'Interesado';
const buyerEmail = d.contact?.email || d.buyer_email || d.email || '';
const buyerPhone = d.contact?.phone || d.buyer_phone || '';
const message    = (d.message || '').toString().slice(0, 800);

// El lookup puede fallar (lead sin vehicle_id, p.ej. asistente) → degradar con elegancia
const hasVehicle  = look && look.brand_name;
const vehicleTitle = hasVehicle
  ? [look.brand_name, look.model_name, look.year].filter(Boolean).join(' ')
  : 'el vehículo de tu interés';
const vehicleUrl = (hasVehicle && look.slug)
  ? `${MARKET_URL}/coches/${look.slug}`
  : MARKET_URL;
const dealerName  = look?.dealer?.name  || 'el vendedor profesional';
const dealerEmail = look?.dealer?.email || '';

const buyerHtml = `<p>Hola ${buyerName},</p>
<p>Hemos enviado tu consulta sobre <strong>${vehicleTitle}</strong> a ${dealerName}.</p>
<p>El vendedor profesional se pondrá en contacto contigo lo antes posible.</p>
<p><a href="${vehicleUrl}">Ver la ficha del vehículo →</a></p>
<p>El equipo de Black Label Market</p>`;

const dealerHtml = `<p>Has recibido una nueva consulta en Black Label Market.</p>
<p><strong>Vehículo:</strong> ${vehicleTitle}<br>
<strong>Interesado:</strong> ${buyerName}<br>
<strong>Email:</strong> ${buyerEmail}${buyerPhone ? '<br><strong>Teléfono:</strong> ' + buyerPhone : ''}</p>
${message ? '<p><strong>Mensaje:</strong> ' + message + '</p>' : ''}
<p><a href="${MARKET_URL}/dashboard/oportunidades">Ver en tu panel →</a></p>`;

const slackPayload = {
  text: `:inbox_tray: *Nuevo lead* — ${buyerName} sobre *${vehicleTitle}*\n`
    + `Dealer: ${dealerName}${dealerEmail ? ' · ' + dealerEmail : ''}\n`
    + `Comprador: ${buyerEmail}${buyerPhone ? ' · ' + buyerPhone : ''}`
    + `${message ? '\n💬 ' + message : ''}`
};

return [{
  json: {
    ...ev,
    buyerName, buyerEmail, dealerName, dealerEmail, vehicleTitle, slackPayload,
    buyerEmailPayload: buyerEmail ? {
      from: MAIL_FROM, to: [buyerEmail],
      subject: `Hemos enviado tu consulta — ${vehicleTitle}`,
      html: buyerHtml + legalFooter
    } : null,
    dealerEmailPayload: dealerEmail ? {
      from: MAIL_FROM, to: [dealerEmail],
      subject: `Nueva consulta: ${vehicleTitle}`,
      html: dealerHtml + legalFooter
    } : null
  }
}];

const legalFooter = `<div style="margin-top:24px;padding-top:14px;border-top:1px solid #ddd;font-size:11px;color:#777;line-height:1.5">Black Label Market es una marca de <strong>KAZAWEB, S.L.U.</strong> (NIF B42761254), con domicilio en Lugar Rebordelo nº 35, Planta 2, 15930 Boiro, A Coruña. Inscrita en el Registro Mercantil de Santiago de Compostela, Tomo 395, Folio 51, Hoja SC-51053.<br>Puedes solicitar la baja de comunicaciones o ejercer tus derechos de privacidad escribiendo a <a href="mailto:privacidad@blacklabelmarket.es">privacidad@blacklabelmarket.es</a>. Consulta nuestra <a href="https://blacklabelmarket.es/legal/privacidad">Política de Privacidad</a>.</div>`;

const ev = $input.first().json;
const d = ev.data || {};
const MAIL_FROM  = 'Black Label Market <hola@blacklabelmarket.es>';
const MARKET_URL = 'https://blacklabelmarket.es';

const name     = d.contact?.name  || d.name  || 'Interesado';
const email    = d.contact?.email || d.email || '';
const brand    = d.brand || '';
const model    = d.model || '';
const budget   = d.budget || d.budget_text || '';
const timeline = d.timeframe || d.timeline || '';

const TIMELINE_LABELS = {
  immediate: 'Lo antes posible',
  '1_3_months': 'En 1-3 meses',
  '3_6_months': 'En 3-6 meses',
  exploring: 'Explorando opciones'
};
const timelineLabel = TIMELINE_LABELS[timeline] || timeline;

const location = d.location || '';
const vehicleDesc = [brand, model].filter(Boolean).join(' ') || 'tu vehículo a medida';

const slackPayload = {
  text: `:memo: *Nueva solicitud a la carta* — ${name} busca *${vehicleDesc}*\n`
    + [budget ? 'Presupuesto: ' + budget : '', location, timelineLabel ? 'Plazo: ' + timelineLabel : '', email]
        .filter(Boolean).join(' · ')
};

const html = `<p>Hola ${name},</p>
<p>Hemos recibido tu solicitud de <strong>${vehicleDesc}</strong>.</p>
<p>Nuestro equipo la analizará y contactará con los concesionarios especializados más adecuados. Te responderemos en un plazo de 24-48 horas laborables.</p>
${budget ? '<p><strong>Presupuesto:</strong> ' + budget + '</p>' : ''}
${timelineLabel ? '<p><strong>Plazo:</strong> ' + timelineLabel + '</p>' : ''}
<p>El equipo de Black Label Market</p>`;

return [{
  json: {
    ...ev,
    name, email, slackPayload,
    emailPayload: email ? {
      from: MAIL_FROM, to: [email],
      subject: `Solicitud recibida: ${vehicleDesc} — Black Label Market`,
      html: html + legalFooter
    } : null
  }
}];

