const d = ($input.first().json.data) || {};
const c = d.contact || {};
const ap = d.appointment || {};
const dealer = d.dealer || {};
const veh = d.vehicle || {};
const links = d.calendar_links || {};
const MAIL_FROM = 'Black Label Market <hola@blacklabelmarket.es>';
const MARKET_URL = 'https://blacklabelmarket.es';
const vehTitle = veh.title || 'el vehículo';
const when = ap.label || '';
const place = ap.mode === 'video' ? 'Videollamada' : (ap.location_text || dealer.name || 'En el showroom');
const instructions = ap.instructions || '';

const btn = (href, label, primary) => `<a href="${href}" style="display:inline-block;background:${primary ? '#C6A64B' : 'transparent'};color:${primary ? '#0B0B0B' : '#C6A64B'};border:1px solid #C6A64B;text-decoration:none;padding:10px 20px;border-radius:4px;font-weight:700;font-size:14px;margin:4px 6px 4px 0;">${label}</a>`;
const calBtns = [links.google ? btn(links.google, 'Añadir a Google Calendar', true) : '', links.outlook ? btn(links.outlook, 'Outlook', false) : ''].join('');

const buyerHtml = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"></head>
<body style="font-family:Arial,sans-serif;color:#1a1a1a;margin:0;padding:0;">
