<div style="color:#C6A64B;font-size:22px;font-weight:700;margin-bottom:8px;">Tu visita está confirmada</div>
<p style="color:#555;font-size:14px;margin-bottom:24px;">Has reservado una visita para ver este vehículo en ${dealer.name || 'el showroom'}.</p>
<div style="background:#f8f8f8;border:1px solid #e0e0e0;border-radius:8px;padding:20px;margin-bottom:24px;">
<div style="font-size:18px;font-weight:600;margin-bottom:8px;">${vehTitle}</div>
<div style="font-size:15px;margin:4px 0;"><strong>Cuándo:</strong> ${when}</div>
<div style="font-size:15px;margin:4px 0;"><strong>Dónde:</strong> ${place}</div>
${instructions ? `<div style="font-size:14px;color:#555;margin-top:8px;">${instructions}</div>` : ''}
</div>
