<div style="margin-top:24px;font-size:12px;color:#888;">Black Label Market · <a href="${MARKET_URL}" style="color:#C6A64B;">${MARKET_URL}</a></div>
</div></body></html>`;

const dealerHtml = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"></head>
<body style="font-family:Arial,sans-serif;color:#1a1a1a;margin:0;padding:0;">
<div style="max-width:580px;margin:0 auto;padding:32px 24px;">
<div style="color:#C6A64B;font-size:22px;font-weight:700;margin-bottom:8px;">Nueva cita reservada</div>
