<div style="font-size:15px;margin:4px 0;"><strong>Cuándo:</strong> ${when}</div>
<div style="font-size:15px;margin:4px 0;"><strong>Dónde:</strong> ${place}</div>
</div>
<div style="background:#fff;border:1px solid #e0e0e0;border-radius:8px;padding:20px;margin-bottom:24px;">
<div style="font-size:13px;text-transform:uppercase;letter-spacing:1px;color:#888;margin-bottom:8px;">Datos del comprador</div>
<div style="font-size:15px;margin:3px 0;">${c.name || ''}</div>
<div style="font-size:15px;margin:3px 0;"><a href="mailto:${c.email}" style="color:#C6A64B;">${c.email || ''}</a></div>
${c.phone ? `<div style="font-size:15px;margin:3px 0;"><a href="tel:${c.phone}" style="color:#C6A64B;">${c.phone}</a></div>` : ''}
</div>
<div style="margin-bottom:16px;">${calBtns}</div>
<div style="margin-top:24px;font-size:12px;color:#888;">Black Label Market · <a href="${MARKET_URL}" style="color:#C6A64B;">${MARKET_URL}</a></div>
</div></body></html>`;

const slackText = `📅 *Nueva cita reservada* — ${vehTitle}\n*Cuándo:* ${when} · *Dónde:* ${place}\n*Comprador:* ${c.name || ''} (${c.email || ''}${c.phone ? ', ' + c.phone : ''})`;

return [{ json: {
  buyerEmailPayload: c.email ? { from: MAIL_FROM, to: [c.email], subject: `Cita confirmada: ${vehTitle} · ${when}`, html: buyerHtml + legalFooter } : null,
  dealerEmailPayload: dealer.email ? { from: MAIL_FROM, to: [dealer.email], subject: `Nueva cita: ${vehTitle} · ${when}`, html: dealerHtml + legalFooter } : null,
  slackPayload: { text: slackText },
} }];
